import { AIRPORTS, TIME_ZONES, recommend } from './engine.mjs';

const $ = selector => document.querySelector(selector);
const elements = { origin: $('#origin'), destination: $('#destination'), from: $('#from'), to: $('#to'), budget: $('#budget'), hour: $('#hour') };
const state = { lang: localStorage.getItem('frontier-language') === 'en' ? 'en' : 'zh', routes: [], observations: [], updatedAt: '', apiBase: '', apiReady: false, session: sessionStorage.getItem('frontier-session') || '', email: sessionStorage.getItem('frontier-email') || '', result: null };
const dict = {
  zh: { loadError:'数据加载失败，请稍后再试。', noRoute:'这两个机场目前没有已核实的 Frontier 直飞组合。', noDates:'所选范围没有可推荐的直飞日期。试试扩大范围或更换机场。', invalid:'请选择未来 90 天内的有效日期范围。', rec:'按公开报价日期接近程度排序的候选直飞日期；并非已查询到这些日期的票价', data:'数据更新', estimate:'公开票价推断', insufficient:'价格样本不足', budget:'预算内可能', over:'可能超预算', check:'建议查票', local:'出发机场当地时间', source:'查看班期', evidence:'最近参考报价', reverse:'反向航线', low:'估算可信度低', limited:'估算可信度有限', invite:'邮件日历邀请', download:'下载日历提醒', emailSent:'请检查邮箱里的登录链接。', emailError:'发送失败，请稍后再试。', backendReady:'邮件提醒已连接。登录后可保存行程并接收日历邀请。', backendOff:'邮件服务尚未连接。你仍可规划行程并下载日历提醒；邮箱邀请暂不可用。', signIn:'请先输入邮箱并通过登录链接验证，随后会继续保存所选提醒。', sent:'日历邀请已发送到注册邮箱。', saved:'行程已更新，新的日历邀请已发送。', cancelled:'提醒已取消。', booked:'已标记订票，后续提醒已停止。', emptyTrips:'还没有保存的行程。', cancel:'取消', bookedButton:'已订票', change:'修改时间', retry:'重发邀请', active:'等待查票', done:'已订票', cancelState:'已取消', pending:'发送中', sendError:'发送失败', unauth:'登录已过期，请重新验证邮箱。' },
  en: { loadError:'Could not load data. Please try again.', noRoute:'No verified Frontier nonstop pair for these airports.', noDates:'No recommended nonstop dates in this range. Try widening the range or changing airports.', invalid:'Choose a valid range within the next 90 days.', rec:'Candidate nonstop dates ranked by proximity to observed fare dates; these dates have not been priced directly', data:'Data updated', estimate:'Public fare inference', insufficient:'Not enough fare data', budget:'May fit budget', over:'May exceed budget', check:'Suggested check', local:'Departure airport local time', source:'Schedule source', evidence:'Reference fare', reverse:'Reverse direction', low:'Low confidence', limited:'Limited confidence', invite:'Email calendar invite', download:'Download calendar reminder', emailSent:'Check your email for the sign-in link.', emailError:'Could not send email. Please try again.', backendReady:'Email reminders are connected. Sign in to save a trip and receive a calendar invite.', backendOff:'Email service is not connected yet. You can plan a trip and download a calendar reminder; email invites are unavailable.', signIn:'Verify your email using the sign-in link. Your selected reminder will then be saved.', sent:'Calendar invitation sent to your registered email.', saved:'Trip updated and a new calendar invitation sent.', cancelled:'Reminder canceled.', booked:'Marked booked. Future reminders are stopped.', emptyTrips:'No saved trips yet.', cancel:'Cancel', bookedButton:'Booked', change:'Change time', retry:'Resend invite', active:'Waiting to check', done:'Booked', cancelState:'Canceled', pending:'Sending', sendError:'Send failed', unauth:'Sign-in expired. Please verify your email again.' }
};
const t = key => dict[state.lang][key];
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),3500); }
function formatDate(date, options={}) { return new Date(`${date}T12:00:00Z`).toLocaleDateString(state.lang==='zh'?'zh-CN':'en-US',{timeZone:'UTC',year:'numeric',month:'short',day:'numeric',weekday:'short',...options}); }
function formatObserved(value) { return new Date(value).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'America/Los_Angeles'}); }
function input() { return Object.fromEntries(Object.entries(elements).map(([key,element])=>[key,element.value])); }
function setLanguage(lang) {
  state.lang=lang; localStorage.setItem('frontier-language',lang); document.documentElement.lang=lang==='zh'?'zh-CN':'en';
  document.querySelectorAll('[data-zh]').forEach(el=>{ const value=el.dataset[lang]; if(el.tagName==='H1')el.innerHTML=value; else el.textContent=value; });
  $('#lang').textContent=lang==='zh'?'English':'中文'; renderStatus(); if(state.result)renderResults(); renderTrips();
}
function renderStatus(){const box=$('#backend-status');box.textContent=state.apiReady?t('backendReady'):t('backendOff');box.classList.toggle('offline',!state.apiReady);$('#email-form').hidden=!state.apiReady||!!state.session;$('#session-area').hidden=!state.apiReady||!state.session;$('#user-email').textContent=state.email;}
function renderResults() {
  const result=state.result, q=input(); if(!result)return;
  $('#results').hidden=false; $('#results-title').textContent=`${q.origin} → ${q.destination}`;
  $('#results-note').textContent=result.status==='ok'?t('rec'):result.status==='no_verified_nonstop'?t('noRoute'):t('noDates');
  $('#data-age').textContent=`${t('data')}: ${state.updatedAt.slice(0,10)}`;
  $('#results-empty').hidden=result.options.length>0; $('#results-empty').textContent=$('#results-note').textContent;
  $('#result-cards').innerHTML=result.options.map((option,index)=>{
    const e=option.estimate, time=`${String(option.reminder.localHour).padStart(2,'0')}:00`;
    const evidence=e.kind==='estimate'?`${t('evidence')} $${e.reference.amount} · ${formatDate(e.reference.travelDate)} · ${formatObserved(e.reference.observedAt)} · ${esc(e.reference.fareType)}${e.reference.reverse?' · '+t('reverse'):''}`:t('insufficient');
    const label=option.withinBudget===true?t('budget'):option.withinBudget===false?t('over'):e.kind==='estimate'?(e.confidence==='limited'?t('limited'):t('low')):t('insufficient');
    return `<article class="result-card"><div class="card-top"><span class="pill ${option.withinBudget===false?'warn':''}">${esc(index===0?'★ '+label:label)}</span><span class="muted">${esc(option.origin)} → ${esc(option.destination)}</span></div><div class="date-main">${esc(formatDate(option.travelDate))}<small>Frontier nonstop · <a class="source-link" href="${esc(option.routeSource)}" target="_blank" rel="noreferrer">${t('source')} ↗</a></small></div><div class="price">${e.kind==='estimate'?`$${e.low}–$${e.high}`:'—'}<small>${t('estimate')} · ${e.samples||0} ${state.lang==='zh'?'个样本':'samples'}</small></div><div class="card-row"><span>${t('check')}</span><b>${esc(formatDate(option.reminder.localDate,{weekday:'short',year:undefined}))} ${time}</b></div><div class="evidence">${e.kind==='estimate'?`<a href="${esc(e.reference.source)}" target="_blank" rel="noreferrer">${evidence} ↗</a>`:evidence}<br>${t('local')}: ${esc(option.reminder.timeZone)}</div><div class="card-actions"><button class="secondary" type="button" data-action="remind" data-index="${index}">${state.apiReady?t('invite'):t('download')} ↗</button></div></article>`;
  }).join('');
  $('#results').scrollIntoView({behavior:'smooth',block:'start'});
}
async function api(path,options={}) {const response=await fetch(state.apiBase+path,{...options,headers:{'Content-Type':'application/json',...(state.session?{'Authorization':`Bearer ${state.session}`}:{}) ,...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data;}
function ics(option,method='PUBLISH',uid=`${option.origin}-${option.destination}-${option.travelDate}@frontier-gowild-dashboard`) {
  const at=new Date(option.reminder.at),end=new Date(at.getTime()+30*60000);
  const stamp=date=>date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Frontier GoWild Flight Radar//EN',`METHOD:${method}`,'BEGIN:VEVENT',`UID:${uid}`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(at)}`,`DTEND:${stamp(end)}`,`SUMMARY:Check Frontier GoWild ${option.origin} to ${option.destination}`,`DESCRIPTION:Travel ${option.travelDate}. GoWild availability requires signed-in confirmation on Frontier. https://www.flyfrontier.com/`,`URL:https://www.flyfrontier.com/`,'BEGIN:VALARM','TRIGGER:-PT0M','ACTION:DISPLAY','DESCRIPTION:Check Frontier GoWild','END:VALARM','END:VEVENT','END:VCALENDAR'];
  return lines.join('\r\n')+'\r\n';
}
function downloadCalendar(option) {const blob=new Blob([ics(option)],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`frontier-${option.origin}-${option.destination}-${option.travelDate}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function createReminder(option) {if(!state.apiReady){downloadCalendar(option);return;}if(!state.session){sessionStorage.setItem('frontier-pending',JSON.stringify(option));toast(t('signIn'));$('#trips').scrollIntoView({behavior:'smooth'});$('#email').focus();return;}try{await api('/reminders',{method:'POST',body:JSON.stringify({origin:option.origin,destination:option.destination,travelDate:option.travelDate,remindAt:option.reminder.at,timeZone:option.reminder.timeZone,estimate:option.estimate.kind==='estimate'?{low:option.estimate.low,high:option.estimate.high}:null})});toast(t('sent'));await renderTrips();}catch(error){toast(error.message);}}
async function renderTrips(){renderStatus();const list=$('#trip-list');if(!state.session||!state.apiReady){list.innerHTML='';return;}try{const data=await api('/reminders');list.innerHTML=data.reminders.length?data.reminders.map(item=>`<div class="trip-row"><div><b>${esc(item.origin)} → ${esc(item.destination)} · ${esc(formatDate(item.travelDate))}</b><small>${t(item.status==='booked'?'done':item.status==='cancelled'?'cancelState':item.status==='send_failed'?'sendError':item.status==='sending'?'pending':'active')} · ${esc(new Date(item.remindAt).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{timeZone:item.timeZone,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))} ${esc(item.timeZone)}</small></div><div>${item.status==='active'||item.status==='send_failed'?`<button data-action="change" data-id="${esc(item.id)}">${t('change')}</button> <button data-action="booked" data-id="${esc(item.id)}">${t('bookedButton')}</button> <button data-action="cancel" data-id="${esc(item.id)}">${t('cancel')}</button>`:''}${item.status==='send_failed'?` <button data-action="retry" data-id="${esc(item.id)}">${t('retry')}</button>`:''}</div></div>`).join(''):`<p class="muted">${t('emptyTrips')}</p>`;}catch(error){if(error.message.includes('401')){state.session='';sessionStorage.removeItem('frontier-session');toast(t('unauth'));}else list.textContent=error.message;renderStatus();}}
async function init(){
  for(const airport of AIRPORTS){for(const select of [elements.origin,elements.destination]){const option=document.createElement('option');option.value=airport;option.textContent=airport;select.appendChild(option);}}
  elements.origin.value='SFO';elements.destination.value='LAS';const today=new Date(),future=new Date(today.getTime()+21*86400000);elements.from.value=today.toISOString().slice(0,10);elements.to.value=future.toISOString().slice(0,10);
  const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.get('session')){state.session=fragment.get('session');state.email=fragment.get('email')||'';sessionStorage.setItem('frontier-session',state.session);sessionStorage.setItem('frontier-email',state.email);history.replaceState({},'',location.pathname+location.search);}
  try{const [routes,history,config]=await Promise.all([fetch('data/routes.json').then(r=>r.json()),fetch('data/fare-history.json').then(r=>r.json()),fetch('config.json').then(r=>r.json())]);state.routes=routes.routes;state.observations=history.observations;state.updatedAt=history.updatedAt;state.apiBase=(config.apiBase||'').replace(/\/$/,'');if(state.apiBase){await api('/health');state.apiReady=true;}}catch(error){if(!state.routes.length)toast(t('loadError'));}
  setLanguage(state.lang);if(state.session)renderTrips();
  const pending=sessionStorage.getItem('frontier-pending');if(state.session&&pending){sessionStorage.removeItem('frontier-pending');try{await createReminder(JSON.parse(pending));}catch{}}
}
$('#planner-form').addEventListener('submit',event=>{event.preventDefault();try{state.result=recommend(input(),state.routes,state.observations);renderResults();}catch(error){toast(t('invalid'));}});
$('#swap').addEventListener('click',()=>{[elements.origin.value,elements.destination.value]=[elements.destination.value,elements.origin.value];});
$('#lang').addEventListener('click',()=>setLanguage(state.lang==='zh'?'en':'zh'));
$('#result-cards').addEventListener('click',event=>{const button=event.target.closest('[data-action="remind"]');if(button)createReminder(state.result.options[Number(button.dataset.index)]);});
$('#email-form').addEventListener('submit',async event=>{event.preventDefault();try{await api('/auth/start',{method:'POST',body:JSON.stringify({email:$('#email').value.trim()})});$('#auth-message').textContent=t('emailSent');}catch(error){$('#auth-message').textContent=t('emailError')+' '+error.message;}});
$('#sign-out').addEventListener('click',()=>{state.session='';state.email='';sessionStorage.removeItem('frontier-session');sessionStorage.removeItem('frontier-email');renderStatus();});
$('#trip-list').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const id=button.dataset.id,action=button.dataset.action;try{if(action==='change'){const item=(await api('/reminders')).reminders.find(row=>row.id===id);if(!item)return;const next=prompt(state.lang==='zh'?'输入前一天当地时间（00、08、12 或 18）':'Enter day-before local hour (00, 08, 12, or 18)',String(new Date(item.remindAt).toLocaleString('en-US',{timeZone:item.timeZone,hour:'numeric',hourCycle:'h23'})));if(next===null)return;const hour=Number(next);if(![0,8,12,18].includes(hour))throw new Error('Choose 00, 08, 12 or 18');const {bookingReminder}=await import('./engine.mjs');const reminder=bookingReminder(item.travelDate,item.origin,hour);await api(`/reminders/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({remindAt:reminder.at})});toast(t('saved'));}else if(action==='retry'){await api(`/reminders/${encodeURIComponent(id)}/retry`,{method:'POST'});toast(t('sent'));}else{await api(`/reminders/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status:action==='booked'?'booked':'cancelled'})});toast(t(action==='booked'?'booked':'cancelled'));}await renderTrips();}catch(error){toast(error.message);}});
init();
